2.4 TCMSP v2.3

rm(list = ls())

load("../data/qfd_ingredients/ingredients.RData")

tcmsp &lt;- read.xlsx("../data/qfd_targets/tcmsp/tcmsp_qfd_targets.xlsx") |&gt;
  dplyr::mutate(
    Source = "TCMSP",
    Class = case_when(
    validated !="validated" ~ "predicted",
    TRUE ~ "validated"),
    Score.SVM = SVM_score
  ) |&gt;
  dplyr::select(MOL_ID,Entry,Source, Score.SVM, Class) 

targets.tcmsp &lt;- ingredients  |&gt;
  separate_rows(TCMSP.ID, sep = ";") |&gt;
  mutate(TCMSP.ID = trimws(TCMSP.ID)) |&gt;
  left_join(tcmsp, by = c("TCMSP.ID" = "MOL_ID"), relationship = "many-to-many") |&gt;
  dplyr::select(No.,Abbreviation,Ingredient,Type,PubChem.CID,Entry, Source, Score.SVM, Class) |&gt;
  distinct(Abbreviation,PubChem.CID,Entry, Source, Class, .keep_all = TRUE) |&gt;
  dplyr::filter(if_all(everything(), ~ !is.na(.x))) |&gt;
  arrange(No., Entry)

save(targets.tcmsp, file = "../data/qfd_targets/tcmsp/targets.tcmsp.RData")

