  dplyr::select(CID,Uniplot, Source,`Norm Fit`,Class) |&gt;
  distinct(CID, Uniplot, .keep_all = TRUE) 

targets.pharm &lt;- ingredients |&gt;
  mutate(PubChem.CID = as.character(PubChem.CID)) |&gt;
