  dplyr::select(No.,Abbreviation,Ingredient,Type,PubChem.CID,Uniplot, Source,`Norm Fit`, Class) |&gt;
  distinct(Abbreviation,PubChem.CID, Uniplot, Source, Class, .keep_all = TRUE) |&gt;
