2.9 SEA

rm(list = ls())

source("utils.R")

load("../data/qfd_ingredients/ingredients.RData")

# Process SEA results (confidence filters)
sea &lt;- read.csv("../data/qfd_targets/sea/sea-results.xls") |&gt;
  mutate(CID = as.numeric(gsub("C","",Query.ID)), .before = 1) |&gt;
  arrange(CID) |&gt;
  mutate(CID = as.character(CID)) |&gt;
  dplyr::select(-Query.ID) |&gt;
  dplyr::filter(grepl("_HUMAN", Target.ID)) |&gt;
  distinct(CID, Target.ID, .keep_all = TRUE) |&gt;
  dplyr::filter(!is.na(Target.ID)) |&gt;
  mutate(Source = "SEA", Class = "predicted") |&gt;
  dplyr::select(CID, Target.ID, Source, P.Value, Max.Tc, Class) |&gt;
  distinct(CID, Target.ID, .keep_all = TRUE) 

targets.sea &lt;- ingredients |&gt;
  mutate(PubChem.CID = as.character(PubChem.CID)) |&gt;
  left_join(sea, by = c("PubChem.CID" = "CID"), relationship = "many-to-many") |&gt;
  dplyr::select(No.,Abbreviation,Ingredient,Type,PubChem.CID,Target.ID, Source, P.Value, Max.Tc,Class) |&gt;
  distinct(Abbreviation,PubChem.CID, Target.ID, Source, Class, .keep_all = TRUE) |&gt;
  dplyr::filter(if_all(everything(), ~ !is.na(.x))) |&gt;
  arrange(No., Target.ID)

# Save processed SEA targets
save(targets.sea, file = "../data/qfd_targets/sea/targets.sea.RData")

